function renderRoofPage({DATA,MODEL,FACTS,$,fmt,esc,unit,factBtn,sheetBtn,heading,roofGeometryCard,activateTab}){const timber=DATA.facts.filter(f=>f.entity.startsWith('timber.')&&f.property==='name');
 $('roof-reference').innerHTML=heading('КД-2–4 · АР-8, 11, 22','Чертежи и узлы кровли','Локальные 3D-разрезы, оригиналы и ведомость древесины.')+
 `<div class="callout"><b>Открыты I003 / I004 / I007 / I009</b>Есть расхождения размерной цепочки, объёмов древесины, направления подписей осей и сечения лежня. Узлы АР-11 информационные; АР-22 требует сверки размеров на месте. Неизвестные узлы примыканий и крепежа не дорисованы как утверждённые.</div>
 <div class="metric-grid"><div class="metric"><div class="eyebrow">ПОДПИСАННЫЙ УКЛОН</div><strong>38 <em>°</em></strong>${factBtn('roof.pitch','АР-8')}</div><div class="metric"><div class="eyebrow">ПЛОЩАДЬ ПО ПРОЕКТУ</div><strong>300,00 <em>м²</em></strong>${factBtn('building.roof_area','АР-1')}</div><div class="metric"><div class="eyebrow">СТРОПИЛЬНАЯ НОГА</div><strong>50 × 200 <em>мм</em></strong>${factBtn('timber.1.width','КД-4')}</div><div class="metric"><div class="eyebrow">OSB-3</div><strong>12 <em>мм</em></strong>${factBtn('roof.osb.thickness','300,0 м² · КД-4')}</div></div>
 <div class="buttons-row"><button id="show-roof-model">К сцене каркаса</button><button data-roof-detail="post12-shoe">Опора стойки № 12 в 3D</button>${sheetBtn('house_1',9,'АР-8 · план кровли')}${sheetBtn('house_2',22,'КД-2 · схема элементов')}${sheetBtn('house_2',23,'КД-3 · узлы и сечения')}${sheetBtn('house_2',24,'КД-4 · ведомость')}</div>
 ${roofGeometryCard()}<div class="card"><h3>Общий деревянный каркас</h3><p>Стропила, диагонали, прогоны, стойки и опорные линии доступны в3D. Фазы, посадки и часть опор имеют открытые условияI021.</p><div class="buttons-row"><button data-frame-open>К сцене каркаса ↑</button><button data-roof-frame>Сверка и источники ↗</button></div></div><div class="node-grid">${MODEL.roof_nodes.map(n=>`<article class="node-card"><img loading="lazy" src="${DATA.crops[n.id]}" alt="${esc(n.title)}" data-node="${n.id}"><div class="node-body"><div class="eyebrow">${esc(n.reference)}</div><h3>${esc(n.title)}</h3>${n.issue_ids.length?`<span class="status amber">${n.issue_ids.join(' / ')}</span>`:''}<p>${esc(n.note)}</p><button data-node="${n.id}">Открыть узел ↗</button>${(DATA.roof_detail_ids?.includes(n.id)??MODEL.roof_details.some(d=>d.id===n.id))?`<button class="secondary" data-roof-detail="${n.id}">Разобрать в 3D ↗</button>`:""}</div></article>`).join('')}</div>
 <div class="section-grid"><div class="card"><h3>Слои покрытия из проекта</h3><table><thead><tr><th>Слой / элемент</th><th>Размер / название</th></tr></thead><tbody><tr><td>Покрытие</td><td>Мягкая черепица RUFLEX</td></tr><tr><td>Настил</td><td>${factBtn('roof.osb.thickness','OSB-3 · 12 мм')}</td></tr><tr><td>Обрешётка</td><td>100 × 25 мм · КД-4</td></tr><tr><td>Контробрешётка</td><td>50 × 50 мм · КД-4</td></tr><tr><td>Стропила</td><td>50 × 200 мм · КД-4</td></tr><tr><td>Межстропильное утепление</td><td>${factBtn('roof.insulation_thickness','200 мм')}</td></tr></tbody></table><p style="margin-top:15px">Окончательный состав покрытия КД-1 оставляет подрядчику по альбому выбранной кровли. Не превращаем информационные узлы в новое проектное решение.</p>${sheetBtn('house_1',12,'АР-11 · материалы и узлы')}</div><div class="card"><h3>Расхождения в ведомости древесины</h3><div class="formula">Поз.14: 2 × 0,2 × 0,2 × 3,465 = 0,2772 м³<br>Ведомость: 0,29 м³<br><br>Поз.17: 2 × 0,2 × 0,2 × 2,785 = 0,2228 м³<br>Ведомость: 0,23 м³<br><br>Поз.21: 66 × 0,15 × 0,15 = 1,485 м³<br>Ведомость: 1,45 м³</div><p>Расчёт и подпись хранятся отдельно. Расход древесины на резку и подгонку в ведомости не учтён.</p>${sheetBtn('house_2',24,'КД-4 · оригинальные значения')}</div></div>
 <div class="card"><h3>Полная ведомость деревянных позиций</h3><div class="table-wrap"><table><thead><tr><th>Позиция</th><th>Элемент</th><th>Сечение, мм</th><th>Длина, мм</th><th>Количество</th><th>Объём ведомости, м³</th><th>Источник</th></tr></thead><tbody>${timber.map(f=>{const e=f.entity,p=id=>FACTS.get(e+'.'+id)?.value??'—',q=FACTS.get(e+'.quantity');return `<tr><td>${esc(e.slice(7))}</td><td>${esc(f.value)}</td><td class="number">${p('width')} × ${p('height')}${p('plies')==='2'?' ×2':''}</td><td class="number">${p('length')}</td><td class="number">${p('quantity')} ${q?unit(q.unit):''}</td><td class="number ${FACTS.get(e+'.listed_volume')?.issue_id?'check-bad':''}">${p('listed_volume')}</td><td>${factBtn(e+'.listed_volume','КД-4')}</td></tr>`;}).join('')}</tbody></table></div></div>`;
 $('show-roof-model').onclick=()=>{$('roof-scene-mount').scrollIntoView();};
}

export { renderRoofPage };
